package com.craft.world;

import java.util.Random;

/**
 * Turns a seed and a chunk coordinate into terrain. Entirely deterministic and free of shared
 * state, so chunks can be generated on worker threads and — crucially — an unmodified chunk
 * can be thrown away and regenerated byte-identically instead of being saved to disk.
 */
public class WorldGen {

    public static final int SEA_LEVEL = 62;
    private static final int MIN_HEIGHT = 4;
    private static final int MAX_HEIGHT = Chunk.HEIGHT - 10;

    private final long seed;

    private final Noise continentNoise;
    private final Noise hillNoise;
    private final Noise mountainNoise;
    private final Noise ridgeNoise;
    private final Noise temperatureNoise;
    private final Noise humidityNoise;
    private final Noise tunnelNoiseA;
    private final Noise tunnelNoiseB;
    private final Noise cavernNoise;
    private final Noise oreNoise;
    private final Noise patchNoise;

    public WorldGen(long seed) {
        this.seed = seed;
        // Separate permutation tables rather than domain offsets: independent fields never
        // correlate, so mountains do not quietly track the temperature map.
        this.continentNoise = new Noise(seed);
        this.hillNoise = new Noise(seed + 1);
        this.mountainNoise = new Noise(seed + 2);
        this.ridgeNoise = new Noise(seed + 3);
        this.temperatureNoise = new Noise(seed + 4);
        this.humidityNoise = new Noise(seed + 5);
        this.tunnelNoiseA = new Noise(seed + 6);
        this.tunnelNoiseB = new Noise(seed + 7);
        this.cavernNoise = new Noise(seed + 8);
        this.oreNoise = new Noise(seed + 9);
        this.patchNoise = new Noise(seed + 10);
    }

    public long getSeed() {
        return seed;
    }

    // ------------------------------------------------------------------ terrain shape

    /** The y of the topmost solid block at a world column. Pure function of the seed. */
    public int heightAt(int worldX, int worldZ) {
        double continent = continentNoise.fbm2(worldX, worldZ, 4, 1 / 640.0, 0.5);
        double hills = hillNoise.fbm2(worldX, worldZ, 4, 1 / 110.0, 0.5);

        // A broad mask decides *where* mountains are allowed, and the ridged field decides
        // their shape. Without the mask, ridges would cover the whole world evenly.
        double mask = mountainNoise.fbm2(worldX, worldZ, 2, 1 / 480.0, 0.5) * 0.5 + 0.5;
        mask = smoothstep(0.66, 0.95, mask);
        double ridge = ridgeNoise.ridged2(worldX, worldZ, 4, 1 / 220.0, 0.55);

        // The land base sits well above sea level and the continent term swings hard, so the
        // coast is steep. A gentler slope would leave a wide band of columns sitting within a
        // couple of blocks of sea level, and the whole world would read as beach.
        double height = SEA_LEVEL + 10 + continent * 42 + hills * 10 + mask * ridge * 40;
        return (int) Math.max(MIN_HEIGHT, Math.min(MAX_HEIGHT, Math.round(height)));
    }

    public Biome biomeAt(int worldX, int worldZ) {
        return biomeAt(worldX, worldZ, heightAt(worldX, worldZ));
    }

    public Biome biomeAt(int worldX, int worldZ, int height) {
        if (height <= SEA_LEVEL - 2) {
            return Biome.OCEAN;
        }
        // A three-block band, not a range: with terrain this smooth, every extra block of
        // beach tolerance turns into percent of the world's surface.
        if (height <= SEA_LEVEL + 1) {
            return Biome.BEACH;
        }

        double temperature = temperatureNoise.fbm2(worldX, worldZ, 3, 1 / 520.0, 0.5);
        double humidity = humidityNoise.fbm2(worldX, worldZ, 3, 1 / 430.0, 0.5);

        // Altitude cools things down, which is what puts snow on peaks in a warm region.
        temperature -= Math.max(0, height - SEA_LEVEL - 20) * 0.022;

        if (height > SEA_LEVEL + 40) {
            return temperature < -0.15 ? Biome.SNOWY_PEAKS : Biome.MOUNTAINS;
        }
        if (temperature < -0.45) {
            return Biome.SNOWY;
        }
        if (height > SEA_LEVEL + 28) {
            return Biome.MOUNTAINS;
        }
        if (temperature > 0.32 && humidity < -0.05) {
            return Biome.DESERT;
        }
        if (humidity > 0.30) {
            return temperature > 0.05 ? Biome.FOREST : Biome.BIRCH_FOREST;
        }
        if (humidity > 0.08) {
            return Biome.FOREST;
        }
        return Biome.PLAINS;
    }

    // -------------------------------------------------------------------- chunk build

    /** Fills a chunk with terrain, then decorates it. The chunk is untouched by anything else. */
    public void generate(Chunk chunk) {
        int originX = chunk.originX();
        int originZ = chunk.originZ();

        for (int x = 0; x < Chunk.SIZE_X; x++) {
            for (int z = 0; z < Chunk.SIZE_Z; z++) {
                int worldX = originX + x;
                int worldZ = originZ + z;

                int height = heightAt(worldX, worldZ);
                Biome biome = biomeAt(worldX, worldZ, height);
                buildColumn(chunk, x, z, worldX, worldZ, height, biome);
            }
        }

        carveCaves(chunk);
        Decorator.decorate(this, chunk);
        chunk.rebuildHeightmap();
    }

    private void buildColumn(Chunk chunk, int x, int z, int worldX, int worldZ,
                             int height, Biome biome) {
        int subsurfaceTop = height - 1;
        int subsurfaceBottom = height - biome.subsurfaceDepth;

        for (int y = 0; y <= height; y++) {
            int id;
            if (y == 0) {
                id = Blocks.BEDROCK.id;
            } else if (y == height) {
                id = surfaceBlockFor(biome, worldX, worldZ, height).id;
            } else if (y >= subsurfaceBottom && y <= subsurfaceTop) {
                id = biome.subsurface.id;
            } else {
                id = stoneBlockFor(worldX, y, worldZ);
            }
            chunk.setBlockRaw(x, y, z, id);
        }

        // Everything from the terrain top up to sea level is water. Caves are carved after
        // this and skip water, so the sea is never punched through from below.
        for (int y = height + 1; y <= SEA_LEVEL; y++) {
            chunk.setBlockRaw(x, y, z, Blocks.WATER.id);
        }

        if (biome == Biome.SNOWY && height > SEA_LEVEL + 1 && height + 1 < Chunk.HEIGHT) {
            chunk.setBlockRaw(x, height + 1, z, Blocks.SNOW.id);
        }
    }

    private BlockType surfaceBlockFor(Biome biome, int worldX, int worldZ, int height) {
        if (biome == Biome.MOUNTAINS) {
            // Grass creeps up the lower slopes; bare rock takes over higher up.
            double patch = patchNoise.fbm2(worldX, worldZ, 2, 1 / 40.0, 0.5);
            if (height < SEA_LEVEL + 36 && patch > -0.1) {
                return Blocks.GRASS;
            }
            return patch > 0.35 ? Blocks.GRAVEL : Blocks.STONE;
        }
        if (biome == Biome.OCEAN) {
            return patchNoise.fbm2(worldX, worldZ, 2, 1 / 30.0, 0.5) > 0.25
                    ? Blocks.GRAVEL : Blocks.SAND;
        }
        return biome.surface;
    }

    /** Stone with veined ore and occasional rock variety, chosen from 3D noise. */
    private int stoneBlockFor(int worldX, int y, int worldZ) {
        BlockType ore = oreAt(worldX, y, worldZ);
        if (ore != null) {
            return ore.id;
        }

        double variety = patchNoise.fbm3(worldX, y, worldZ, 2, 1 / 34.0, 0.5);
        if (variety > 0.55) {
            return Blocks.GRANITE.id;
        }
        if (variety < -0.55) {
            return Blocks.DIORITE.id;
        }
        if (y < 26 && variety > 0.35) {
            return Blocks.SLATE.id;
        }
        return Blocks.STONE.id;
    }

    /**
     * Ore veins from thresholded 3D noise rather than per-block dice rolls, which is what makes
     * them come out as connected pockets instead of lonely specks.
     *
     * <p>Single-octave 3D Perlin has a standard deviation near 0.27, so these thresholds sit
     * between two and three sigma out. Measured volume fractions: 0.60 catches 0.85% of a band,
     * 0.64 catches 0.55%, 0.72 catches 0.18% and 0.76 catches 0.08% — which lands total ore at
     * a little over 1% of stone.
     *
     * <p>Rarest first: a diamond position must not be claimed by the far more common coal test.
     */
    private BlockType oreAt(int worldX, int y, int worldZ) {
        if (y >= 1 && y <= 16
                && oreNoise.noise3(worldX / 6.5, y / 6.5 + 90, worldZ / 6.5) > 0.76) {
            return Blocks.DIAMOND_ORE;
        }
        if (y >= 2 && y <= 32
                && oreNoise.noise3(worldX / 7.0 + 60, y / 7.0, worldZ / 7.0) > 0.72) {
            return Blocks.GOLD_ORE;
        }
        if (y >= 3 && y <= 64
                && oreNoise.noise3(worldX / 7.5, y / 7.5, worldZ / 7.5 + 40) > 0.64) {
            return Blocks.IRON_ORE;
        }
        if (y >= 5 && y <= 92
                && oreNoise.noise3(worldX / 8.5 + 20, y / 8.5 + 20, worldZ / 8.5) > 0.60) {
            return Blocks.COAL_ORE;
        }
        return null;
    }

    // -------------------------------------------------------------------------- caves

    private void carveCaves(Chunk chunk) {
        int originX = chunk.originX();
        int originZ = chunk.originZ();

        for (int x = 0; x < Chunk.SIZE_X; x++) {
            for (int z = 0; z < Chunk.SIZE_Z; z++) {
                int worldX = originX + x;
                int worldZ = originZ + z;
                int top = Math.min(Chunk.HEIGHT - 1, heightAt(worldX, worldZ));

                for (int y = 2; y < top - 1; y++) {
                    int id = chunk.getBlockId(x, y, z);
                    if (!isCarvable(id)) {
                        continue;
                    }
                    if (isCave(worldX, y, worldZ)) {
                        chunk.setBlockRaw(x, y, z, Blocks.AIR.id);
                    }
                }
            }
        }
    }

    private boolean isCarvable(int id) {
        BlockType type = Blocks.byId(id);
        return type != Blocks.AIR && type != Blocks.WATER && type != Blocks.BEDROCK;
    }

    /** How close to zero a tunnel field must be to carve. Each band is roughly 15% of samples. */
    private static final double TUNNEL_BAND = 0.07;

    /**
     * Two cave systems.
     *
     * <p>Tunnels come from the intersection of two independent noise fields near zero. A single
     * near-zero band would carve a <em>surface</em> through the volume — broad sheets, not
     * caves. Intersecting two such surfaces leaves their line of intersection, which is a
     * winding one-dimensional passage: an actual tunnel. Each band alone catches about 15% of
     * the volume, so their intersection carves a couple of percent.
     *
     * <p>Caverns are a separate high threshold on a coarser field, giving the occasional open
     * chamber for the tunnels to run into.
     */
    private boolean isCave(int worldX, int y, int worldZ) {
        // The vertical squash makes the noise change faster with height, so passages come out
        // wider than they are tall rather than as vertical shafts.
        double a = tunnelNoiseA.fbm3(worldX, y * 2.2, worldZ, 2, 1 / 60.0, 0.5);
        if (Math.abs(a) < TUNNEL_BAND) {
            double b = tunnelNoiseB.fbm3(worldX, y * 2.2, worldZ, 2, 1 / 60.0, 0.5);
            if (Math.abs(b) < TUNNEL_BAND) {
                return true;
            }
        }
        double cavern = cavernNoise.fbm3(worldX, y * 1.7, worldZ, 2, 1 / 78.0, 0.5);
        return cavern > 0.72 && y < 54;
    }

    // ------------------------------------------------------------------------ helpers

    /**
     * The RNG a chunk's decoration pass uses. Depends only on the seed and chunk coordinate,
     * so a neighbour recreating the sequence gets exactly the same trees.
     */
    public Random decorationRandom(int chunkX, int chunkZ) {
        long h = seed;
        h = h * 6364136223846793005L + (chunkX * 341873128712L);
        h = h * 6364136223846793005L + (chunkZ * 132897987541L);
        h ^= (h >>> 33);
        return new Random(h);
    }

    /** Finds a safe standing height for a spawn point at the given column. */
    public int surfaceSpawnY(int worldX, int worldZ) {
        int height = heightAt(worldX, worldZ);
        return Math.max(height + 1, SEA_LEVEL + 1);
    }

    private static double smoothstep(double edge0, double edge1, double x) {
        double t = Math.max(0, Math.min(1, (x - edge0) / (edge1 - edge0)));
        return t * t * (3 - 2 * t);
    }
}
